const { Sequelize, DataTypes } = require('sequelize');

const sequelize = new Sequelize({
  dialect: 'sqlite',
  storage: 'database.sqlite'
});

const User = sequelize.define('User', {
  username: {
    type: DataTypes.STRING,
    unique: true,
    allowNull: false
  }
});

const Project = sequelize.define('Project', {
  name: {
    type: DataTypes.STRING,
    unique: true,
    allowNull: false
  }
});

const UserProject = sequelize.define('UserProject', {
  role: {
    type: DataTypes.STRING,
    allowNull: false
  }
});

User.belongsToMany(Project, { through: UserProject });
Project.belongsToMany(User, { through: UserProject });

module.exports = { sequelize, User, Project, UserProject };
EOF

cat > cli.js << 'EOF'
const { sequelize, User, Project, UserProject } = require('./models');

async function main() {
  await sequelize.sync();

  const args = process.argv.slice(2);
  const command = args[0];

  if (command === 'add') {
    const username = args[1];
    const projectName = args[2];
    const role = args[3];

    const [user] = await User.findOrCreate({ where: { username } });
    const [project] = await Project.findOrCreate({ where: { name: projectName } });

    await UserProject.findOrCreate({
      where: { UserId: user.id, ProjectId: project.id },
      defaults: { role }
    });

    console.log(`Success: ${username} added to ${projectName} as ${role}`);
  } else if (command === 'list') {
    const username = args[1];
    const user = await User.findOne({
      where: { username },
      include: {
        model: Project,
        through: { attributes: ['role'] }
      }
    });

    if (!user) {
      console.log(JSON.stringify([]));
      return;
    }

    const result = user.Projects.map(project => ({
      name: project.name,
      role: project.UserProject.role
    }));

    console.log(JSON.stringify(result, null, 2));
  }

  await sequelize.close();
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
EOF

